def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    import re as _re
    blob = json.dumps({"l": lessons, "q": questions}, ensure_ascii=False)
    if "ERPNext" in blob:
        problems.append(f"  {name}: ERPNext branding leakage")
    if _re.search(r"\b[Ll]aws?\b", blob):
        problems.append(f"  {name}: 'law' register leakage")
    low = blob.lower()
    if "montaigne" in low:
        problems.append(f"  {name}: old case name present")
    for marker in ["certified professional", "the consultant", "consultants", "the academy",
                   "this academy", "engagement", "constitution", "costume", "scar tissue",
                   "witness", "testimony"] + EDITORIAL_BAN:
        if marker in low:
            problems.append(f"  {name}: banned phrase '{marker}'")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        raw = f.read()

    if '"3.193.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.192.0"' not in init:
        sys.exit("ABORT: not at v3.192.0.")

    # 1. Track-wide case rename (covers modules 3-5 rewrites and any old text)
    n_full = raw.count("Montaigne AH")
    raw = raw.replace("Montaigne AH", "BizRetail Ltd")
    n_bare = raw.count("Montaigne")
    raw = raw.replace("Montaigne", "BizRetail")
    data = json.loads(raw)
    print(f"rename: {n_full} x 'Montaigne AH' -> 'BizRetail Ltd', {n_bare} x bare 'Montaigne' -> 'BizRetail'")

    if "sales_invoice" not in data:
        sys.exit("ABORT: sales_invoice module not found in data file.")

    problems = _validate("SELL7", LESSONS_S7, QUESTIONS_S7, 10)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS_S7))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — SELL7 spread failed: {dist}")
        sys.exit(1)
    total = sum(len(l["html"]) for l in LESSONS_S7)
    print(f"SELL 7 v3: {len(LESSONS_S7)} chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS_S7):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["sales_invoice"]["lessons"] = LESSONS_S7
    data["sales_invoice"]["questions"] = bank
    data["sales_invoice"]["desc"] = ("The Sales Invoice, payments, and collections in ZhiftERP: the field walk — template due dates, honest posting dates, rates from the agreement, per-row references, and advance allocation at preparation; the three creation paths — from the Delivery Note for performance, from the Sales Order for the schedule, direct only per policy — and the run's two worklists; the four postings of submission with the e-invoicing rules and the three correction lanes; Payment Entries with remittance-led allocation, partial payments, short-pay routing, and the weekly unallocated read; credit notes — the return tie, value-only exceptions, credit-or-refund settlement; the receivables aging, statement cycle, and dunning configuration; and the four-gear collections procedure from the 7-day pre-due contact to the resolution decision.")

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.192.0"', '"3.193.0"'))
    print("  data: SELLING 7 lessons + bank REPLACED (style v3, textbook manual register); case renamed track-wide")
    print("wrote __version__ -> 3.193.0")


if __name__ == "__main__":
    main()
